"use client";

import React, { useState, useEffect, use } from "react";
import { getProjectById, createProjectTask, updateTaskDates, linkTaskToMaintenance } from "@/lib/process-actions";
import { getAssets } from "@/lib/actions";
import { Calendar, Plus, Link as LinkIcon, AlertCircle, Wrench, ArrowLeft, GripHorizontal } from "lucide-react";
import Link from "next/link";
import { format, addDays, getDaysInMonth, startOfMonth, differenceInDays } from "date-fns";
import { it } from "date-fns/locale";

interface GanttTask {
    id: string;
    title: string;
    startDate: Date;
    endDate: Date;
    status: string;
    linkedWorkOrderId: string | null;
}

export default function ProjectDetail({ params }: { params: Promise<{ id: string }> }) {
    const { id } = use(params);
    const [project, setProject] = useState<any>(null);
    const [assets, setAssets] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);
    const [isAddingTask, setIsAddingTask] = useState(false);

    // Quick Add Form
    const [newTaskTitle, setNewTaskTitle] = useState("");

    // Modal for Maintenance Link
    const [linkingTask, setLinkingTask] = useState<GanttTask | null>(null);
    const [selectedAsset, setSelectedAsset] = useState("");
    const [maintenanceDesc, setMaintenanceDesc] = useState("");

    const loadData = async () => {
        const [projData, assetsData] = await Promise.all([
            getProjectById(id),
            getAssets()
        ]);
        setProject(projData);
        setAssets(assetsData);
        setLoading(false);
    };

    useEffect(() => {
        loadData();
    }, [id]);

    const handleAddTask = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!newTaskTitle) return;

        await createProjectTask({
            projectId: id,
            title: newTaskTitle,
            startDate: new Date(),
            endDate: addDays(new Date(), 3),
            status: "TODO"
        });

        setNewTaskTitle("");
        setIsAddingTask(false);
        loadData();
    };

    const handleLinkMaintenance = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!linkingTask || !selectedAsset) return;

        const res = await linkTaskToMaintenance(linkingTask.id, selectedAsset, maintenanceDesc, id);
        if (res.success) {
            setLinkingTask(null);
            setMaintenanceDesc("");
            setSelectedAsset("");
            loadData();
            alert("Work Order creato con successo e collegato al Task!");
        } else {
            alert(res.message);
        }
    };

    if (loading) return <div className="p-8 text-center animate-pulse">Caricamento Progetto...</div>;
    if (!project) return <div className="p-8 text-center">Progetto non trovato.</div>;

    // Gantt Logic (Simple Timeline View)
    // We visualize a 30-day window starting from the earliest task or today.
    const earliestDate = project.tasks?.length > 0
        ? new Date(Math.min(...project.tasks.map((t: any) => new Date(t.startDate).getTime())))
        : new Date();

    const timelineStart = new Date(earliestDate);
    timelineStart.setHours(0, 0, 0, 0);
    const daysWindow = 30; // Show 30 days
    const dayLabels = Array.from({ length: daysWindow }).map((_, i) => addDays(timelineStart, i));

    const getTaskStyle = (task: any) => {
        const taskStart = new Date(task.startDate);
        const taskEnd = new Date(task.endDate);

        const offsetDays = differenceInDays(taskStart, timelineStart);
        const durationDays = differenceInDays(taskEnd, taskStart) || 1; // min 1 day

        // Calculate percentages based on 30-day window
        const leftPercent = Math.max(0, (offsetDays / daysWindow) * 100);
        const widthPercent = Math.min(100 - leftPercent, (durationDays / daysWindow) * 100);

        return {
            left: `${leftPercent}%`,
            width: `${widthPercent}%`,
        };
    };

    return (
        <div className="space-y-6 max-w-7xl mx-auto p-4 md:p-8 animate-in slide-in-from-bottom duration-500">
            {/* Header */}
            <div className="flex flex-col md:flex-row justify-between items-start gap-4">
                <div>
                    <Link href="/process" className="text-sm font-medium text-slate-500 hover:text-indigo-600 flex items-center gap-1 mb-2">
                        <ArrowLeft className="h-4 w-4" /> Torna a Progetti
                    </Link>
                    <h1 className="text-3xl font-extrabold text-slate-800">{project.title}</h1>
                    <p className="text-slate-500 mt-1">{project.description}</p>
                </div>
                <div className="flex gap-2">
                    <button
                        onClick={() => setIsAddingTask(true)}
                        className="bg-indigo-600 text-white px-4 py-2 rounded-xl flex items-center gap-2 shadow-md hover:bg-indigo-700 transition"
                    >
                        <Plus className="h-4 w-4" /> Aggiungi Task
                    </button>
                    {!project.linkedWorkOrderId && (
                        <button className="bg-white border border-slate-300 text-slate-700 px-4 py-2 rounded-xl hover:bg-slate-50 transition">
                            Modifica Info
                        </button>
                    )}
                </div>
            </div>

            {/* Quick Add Form */}
            {isAddingTask && (
                <form onSubmit={handleAddTask} className="bg-white p-4 rounded-xl border border-indigo-200 shadow-sm flex gap-3 items-center animate-in fade-in zoom-in-95">
                    <input
                        type="text"
                        placeholder="Titolo della nuova attività..."
                        value={newTaskTitle}
                        onChange={e => setNewTaskTitle(e.target.value)}
                        className="flex-1 border rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500"
                        autoFocus
                    />
                    <button type="submit" className="bg-indigo-600 text-white px-4 py-2 rounded-lg text-sm font-medium hover:bg-indigo-700">Salva</button>
                    <button type="button" onClick={() => setIsAddingTask(false)} className="text-slate-500 px-3 py-2 text-sm hover:bg-slate-100 rounded-lg">Annulla</button>
                </form>
            )}

            {/* Visual Gantt Chart Sandbox */}
            <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
                <div className="p-4 border-b border-slate-100 bg-slate-50 flex items-center gap-3">
                    <Calendar className="h-5 w-5 text-indigo-500" />
                    <h3 className="font-bold text-slate-700">Timeline di Progetto (Gantt Interattivo)</h3>
                </div>

                <div className="p-6 overflow-x-auto">
                    <div className="min-w-[800px]">
                        {/* Timeline Header (Days) */}
                        <div className="flex relative border-b border-slate-200 pb-2 mb-4 ml-48">
                            {dayLabels.map((date, i) => (
                                <div key={i} className="flex-1 text-center min-w-[30px] border-l border-slate-100 first:border-l-0">
                                    <div className="text-[10px] font-bold text-slate-400 uppercase">{format(date, 'E', { locale: it })}</div>
                                    <div className="text-xs font-semibold text-slate-700">{format(date, 'd')}</div>
                                </div>
                            ))}
                        </div>

                        {/* Tasks Rows */}
                        <div className="space-y-4">
                            {project.tasks?.length === 0 ? (
                                <div className="text-center py-10 text-slate-400 italic">Nessun task in timeline.</div>
                            ) : (
                                project.tasks?.map((task: any) => (
                                    <div key={task.id} className="relative flex items-center group">
                                        {/* Row Label */}
                                        <div className="w-48 pr-4 py-1 shrink-0 flex items-center justify-between z-10 bg-white">
                                            <div className="truncate text-sm font-medium text-slate-700 flex items-center gap-2">
                                                <GripHorizontal className="h-3 w-3 text-slate-300 opacity-0 group-hover:opacity-100 cursor-grab" />
                                                {task.title}
                                            </div>
                                            {task.linkedWorkOrderId ? (
                                                <Link href={`/work-orders/${task.linkedWorkOrderId}?tab=details`} className="text-amber-600 hover:bg-amber-50 p-1 rounded" title="WO di Manutenzione collegato">
                                                    <Wrench className="h-3.5 w-3.5" />
                                                </Link>
                                            ) : (
                                                <button
                                                    onClick={() => setLinkingTask(task)}
                                                    className="text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 p-1 rounded opacity-0 group-hover:opacity-100 transition-opacity"
                                                    title="Collega a Manutenzione"
                                                >
                                                    <LinkIcon className="h-3.5 w-3.5" />
                                                </button>
                                            )}
                                        </div>

                                        {/* Row Track */}
                                        <div className="flex-1 relative h-10 border-b border-slate-50 border-dashed rounded bg-slate-50/50">
                                            {/* The Task Bar */}
                                            <div
                                                className={`absolute top-1 bottom-1 rounded-md shadow-sm border flex items-center px-3 cursor-pointer hover:brightness-95 transition-all
                                                    ${task.status === 'DONE' ? 'bg-emerald-500 border-emerald-600 text-white' :
                                                        task.linkedWorkOrderId ? 'bg-amber-400 border-amber-500 text-amber-950' :
                                                            'bg-indigo-500 border-indigo-600 text-white'}
                                                `}
                                                style={getTaskStyle(task)}
                                                onClick={() => {
                                                    // In a real app, this would open a side panel. For MVP, we alert.
                                                    alert(`Dettaglio Task: ${task.title}\nStatus: ${task.status}\nInizio: ${format(new Date(task.startDate), 'PP', { locale: it })}\nFine: ${format(new Date(task.endDate), 'PP', { locale: it })}`);
                                                }}
                                            >
                                                <span className="text-[10px] font-bold truncate">{task.title}</span>
                                            </div>
                                        </div>
                                    </div>
                                ))
                            )}
                        </div>
                    </div>
                </div>

                <div className="bg-slate-50 p-3 text-xs text-slate-500 flex justify-between items-center border-t border-slate-100">
                    <div className="flex gap-4">
                        <span className="flex items-center gap-1"><div className="w-3 h-3 rounded bg-indigo-500"></div> Task Standard</span>
                        <span className="flex items-center gap-1"><div className="w-3 h-3 rounded bg-amber-400"></div> Task Manutentivo (WO)</span>
                        <span className="flex items-center gap-1"><div className="w-3 h-3 rounded bg-emerald-500"></div> Completato</span>
                    </div>
                    <span>* Trascina le barre per cambiare le date (Frontend mock: richiede refactor completo per vero drag&drop)</span>
                </div>
            </div>

            {/* Modal for Linking Maintenance */}
            {linkingTask && (
                <div className="fixed inset-0 bg-slate-900/50 backdrop-blur-sm flex items-center justify-center z-50 p-4">
                    <div className="bg-white rounded-2xl shadow-xl max-w-lg w-full overflow-hidden animate-in zoom-in-95 duration-200">
                        <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-indigo-50">
                            <div>
                                <h3 className="font-bold text-indigo-900 flex items-center gap-2">
                                    <Wrench className="h-5 w-5" /> Collega Manutenzione
                                </h3>
                                <p className="text-sm text-indigo-700/70 mt-1">
                                    Invia una richiesta formale di Work Order per il task <strong>"{linkingTask.title}"</strong>.
                                </p>
                            </div>
                        </div>
                        <form onSubmit={handleLinkMaintenance} className="p-6 space-y-4">
                            <div>
                                <label className="block text-sm font-medium text-slate-700 mb-1">Asset/Macchinario Interessato</label>
                                <select
                                    className="w-full border rounded-lg px-3 py-2 focus:ring-2 focus:ring-indigo-500"
                                    value={selectedAsset}
                                    onChange={e => setSelectedAsset(e.target.value)}
                                    required
                                >
                                    <option value="">Seleziona asset...</option>
                                    {assets.map(a => (
                                        <option key={a.id} value={a.id}>{a.name} ({a.model})</option>
                                    ))}
                                </select>
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-slate-700 mb-1">Dettagli per i Tecnici</label>
                                <textarea
                                    className="w-full border rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-indigo-500 bg-slate-50"
                                    rows={4}
                                    value={maintenanceDesc}
                                    onChange={e => setMaintenanceDesc(e.target.value)}
                                    placeholder="Es. Eseguire foratura sul basamento per il nuovo supporto come da disegno IN-001."
                                    required
                                />
                            </div>

                            <div className="bg-amber-50 text-amber-800 p-3 rounded-lg text-sm flex gap-2 items-start border border-amber-200">
                                <AlertCircle className="h-5 w-5 shrink-0" />
                                <p>Un Ordine di Lavoro verrà creato e indirizzato al team di manutenzione. Potrai tracciarne lo stato direttamente da questa timeline.</p>
                            </div>

                            <div className="flex justify-end gap-3 mt-6 pt-4 border-t">
                                <button type="button" onClick={() => setLinkingTask(null)} className="px-4 py-2 font-medium text-slate-600 hover:bg-slate-100 rounded-lg transition">Annulla</button>
                                <button type="submit" className="px-5 py-2 font-medium bg-indigo-600 text-white rounded-lg shadow-md hover:bg-indigo-700 transition">Richiedi Intervento</button>
                            </div>
                        </form>
                    </div>
                </div>
            )}
        </div>
    );
}

"use client";

import { useState } from "react";
import { useParams } from "next/navigation";
import { useWorkOrders } from "@/lib/work-orders-context";
import { useInventory } from "@/lib/inventory-context";
import { useReference } from "@/lib/reference-context";
import {
    ArrowLeft,
    Calendar,
    User,
    CheckCircle2,
    Clock,
    Wrench,
    Box,
    AlertTriangle,
    Banknote,
    Trash2
} from "lucide-react";
import Link from "next/link";
import { WOAssignDialog } from "@/components/work-orders/wo-assign-dialog";
import { WOApproveDialog } from "@/components/work-orders/wo-approve-dialog";
import { updateWorkOrderStatus, reviewWorkOrder, addWorkOrderPart, removeWorkOrderPart } from "@/lib/actions";
import { useRouter } from "next/navigation";
import { useAuth } from "@/lib/auth-context";
import { WOPriorityBadge } from "@/components/work-orders/wo-priority-badge";
import { WOStatusBadge } from "@/components/work-orders/wo-status-badge";
import { WorkOrderChecklist } from "@/components/work-orders/wo-checklist";
import { StatusStepper } from "@/components/work-orders/status-stepper";
import { PrintButton, PrintableWO } from "@/components/work-orders/wo-printable";
import { TimerControls } from "@/components/work-orders/timer-controls";
import { AISuggestions } from "@/components/work-orders/ai-suggestions";

export default function WorkOrderDetailPage() {
    const params = useParams();
    const router = useRouter(); // Use App Router
    const { user } = useAuth();
    const { workOrders, updateWorkOrder } = useWorkOrders();
    const { parts } = useInventory(); // Removed updateQuantity
    const { technicians } = useReference();

    const canManage = user?.role === 'ADMIN' || user?.role === 'SUPERVISOR' || user?.role === 'MAINTAINER';

    // Parts State
    const [isAddingPart, setIsAddingPart] = useState(false);
    const [selectedPartId, setSelectedPartId] = useState("");
    const [partQty, setPartQty] = useState(1);

    // Labor State
    const [isAddingLabor, setIsAddingLabor] = useState(false);
    const [selectedTechId, setSelectedTechId] = useState("");
    const [laborHours, setLaborHours] = useState(1);

    // Dialog State
    const [showApproveDialog, setShowApproveDialog] = useState(false);
    const [assigning, setAssigning] = useState(false);

    const wo = workOrders.find(w => w.id === params.id) || workOrders.find(w => w.id === decodeURIComponent(params.id as string));

    if (!wo) {
        return (
            <div className="flex flex-col items-center justify-center p-12 text-center">
                <h2 className="text-xl font-semibold">Ordine di Lavoro Non Trovato</h2>
                <Link href="/work-orders" className="text-primary hover:underline mt-4 flex items-center gap-2"><ArrowLeft className="h-4 w-4" /> Torna alla Lista</Link>
            </div>
        );
    }

    // Calculate Costs
    const partsCost = wo.partsUsed?.reduce((sum, p) => sum + (p.quantity * p.unitCost), 0) || 0;

    // We need to look up technicians to get rates if not stored on the log. 
    // In a real app, we might store the snapshot of rate at logging time.
    // For now, we'll look up live.
    const laborCost = (wo.laborLogs || []).reduce((sum, log) => {
        const tech = technicians?.find(t => t.id === log.technicianId);
        const rate = tech?.hourlyRate || 0;
        return sum + (log.hours * rate);
    }, 0);

    const totalCost = partsCost + laborCost;

    // Safety checks for context
    if (!parts) console.warn("Inventory context missing or empty");
    if (!technicians) console.warn("Reference context missing or empty");

    const handleAddPart = async (e: React.FormEvent) => {
        e.preventDefault();
        const part = parts?.find(p => p.id === selectedPartId);
        if (!part) {
            alert("Errore: Articolo non trovato o inventario non caricato.");
            return;
        }

        if (part.quantity < partQty) {
            alert("Quantità insufficiente in magazzino!");
            return;
        }

        try {
            const result = await addWorkOrderPart(wo.id, part.id, partQty);
            if (result.success) {
                // Reset UI
                setIsAddingPart(false);
                setSelectedPartId("");
                setPartQty(1);

                // Force data refresh
                // Since updateWorkOrder only updates local, and we mutated server, we should probably fetchWOs again 
                // but context does that on mount. 
                // Simplest is router.refresh() which re-runs server components, but this is a Client Component.
                // However router.refresh() triggers re-fetching of server data passed to client components.
                // But our data comes from Context initialized by `actions`.
                // Actually context loads on mount.
                // We might need to manually trigger reload in context or just reload page.
                // We might need to manually trigger reload in context or just reload page.
                router.refresh(); // Quickest consistent way for now, slightly jarring but safe.
            } else {
                alert("Errore: " + result.message);
            }
        } catch (error) {
            alert("Si è verificato un errore.");
        }
    };

    const handleRemovePart = async (partLinkId: string) => {
        if (!confirm("Rimuovere ricambio e ripristinare la giacenza?")) return;

        try {
            const result = await removeWorkOrderPart(partLinkId);
            if (result.success) {
                router.refresh();
            } else {
                alert("Errore: " + result.message);
            }
        } catch (error) {
            alert("Errore di sistema.");
        }
    };

    const handleAddLabor = (e: React.FormEvent) => {
        e.preventDefault();
        const tech = technicians?.find(t => t.id === selectedTechId);
        if (!tech) return;

        const newLog = {
            id: `LOG-${Date.now()}`,
            technicianId: tech.id,
            technicianName: tech.name,
            hours: laborHours,
            date: new Date().toISOString()
        };

        const currentLogs = wo.laborLogs || [];
        updateWorkOrder(wo.id, { laborLogs: [...currentLogs, newLog] });

        setIsAddingLabor(false);
        setSelectedTechId("");
        setLaborHours(1);
    };

    return (
        <div className="space-y-6 animate-in fade-in duration-500">
            <div className="flex items-center gap-4">
                <Link href="/work-orders" className="p-2 rounded-full hover:bg-muted text-muted-foreground">
                    <ArrowLeft className="h-5 w-5" />
                </Link>
                <div>
                    <h1 className="text-3xl font-bold tracking-tight bg-gradient-to-r from-foreground to-foreground/60 bg-clip-text text-transparent">
                        Dettaglio Ordine di Lavoro
                    </h1>
                    <div className="flex items-center gap-2 text-muted-foreground mt-1">
                        <span className="font-mono bg-muted px-2 rounded text-sm">{wo.id}</span>
                        <span>•</span>
                        <span>Creato il {new Date(wo.createdAt).toLocaleDateString()}</span>
                    </div>
                </div>
                <div className="ml-auto hidden sm:block">
                    <PrintButton contentRef={{ current: typeof document !== 'undefined' ? document.getElementById('printable-content') as HTMLDivElement : null }} />
                </div>
            </div>

            <StatusStepper status={wo.status} />

            <div className="hidden sm:block">
                <PrintableWO wo={wo} hidden />
            </div>

            {/* Timer Controls Banner */}
            <div className="mb-6">
                <TimerControls workOrder={wo} currentUserId={user?.id || ''} canManage={canManage} />
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">

                {/* Left Column: Main Info */}
                <div className="lg:col-span-2 space-y-6">

                    {/* Status & Priority Cards */}
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                        <div className="rounded-xl border bg-card p-6 shadow-sm flex items-center justify-between">
                            <div>
                                <p className="text-sm text-muted-foreground font-medium">Stato</p>
                                <WOStatusBadge status={wo.status} />
                            </div>
                            {/* ... icon ... */}
                        </div>
                        <div className="rounded-xl border bg-card p-6 shadow-sm flex items-center justify-between">
                            <div>
                                <p className="text-sm text-muted-foreground font-medium">Priorità</p>
                                <WOPriorityBadge priority={wo.priority} />
                            </div>
                            {/* ... icon ... */}
                        </div>
                    </div>

                    {/* Description */}
                    <div className="rounded-xl border bg-card p-6 shadow-sm">
                        <h3 className="font-semibold text-lg mb-2">Descrizione</h3>
                        <p className="text-muted-foreground leading-relaxed">
                            {wo.description}
                        </p>

                        <div className="mt-4 mb-4">
                            <AISuggestions assetId={wo.assetId} description={wo.description} />
                        </div>

                        <div className="mt-4 pt-4 border-t flex gap-6 text-sm">
                            <div>
                                <span className="text-muted-foreground block mb-1">Asset</span>
                                <Link href={`/assets/${wo.assetId}`} className="font-medium hover:underline text-primary flex items-center gap-1">
                                    <Box className="h-3 w-3" /> {wo.assetName}
                                </Link>
                            </div>
                            <div>
                                <span className="text-muted-foreground block mb-1">Assegnato a</span>
                                <div className="font-medium flex flex-wrap gap-1">
                                    {wo.technicians && wo.technicians.length > 0 ? (
                                        wo.technicians.map((t: any) => (
                                            <span key={t.id} className="flex items-center gap-1 bg-muted px-1.5 py-0.5 rounded-full text-xs">
                                                <User className="h-3 w-3" /> {t.name}
                                            </span>
                                        ))
                                    ) : (
                                        <div className="flex items-center gap-1">
                                            <User className="h-3 w-3" /> {wo.assignedTo || 'Non assegnato'}
                                        </div>
                                    )}
                                </div>
                            </div>
                            <div>
                                <span className="text-muted-foreground block mb-1">Scadenza</span>
                                <div className="font-medium flex items-center gap-1">
                                    <Calendar className="h-3 w-3" /> {wo.dueDate}
                                </div>
                            </div>
                        </div>
                    </div>

                    {/* Checklist */}
                    <WorkOrderChecklist workOrderId={wo.id} items={wo.checklist} onUpdate={updateWorkOrder} />

                </div>

                {/* Right Column: Actions & Costs */}
                <div className="space-y-6">

                    {/* Quick Actions (Placeholder) */}
                    {/* Actions Workflow */}
                    <div className="rounded-xl border bg-card p-6 shadow-sm">
                        <h3 className="font-semibold text-sm uppercase tracking-wider text-muted-foreground mb-4">Azioni Flusso</h3>
                        <div className="space-y-3">

                            {/* APPROVAL STEP */}
                            {wo.status === 'PENDING_APPROVAL' && (canManage ? (
                                <>
                                    <button
                                        onClick={() => setShowApproveDialog(true)}
                                        className="w-full text-left px-4 py-3 bg-emerald-50 text-emerald-700 hover:bg-emerald-100 border border-emerald-200 rounded-lg text-sm font-medium transition-colors flex items-center gap-3 shadow-sm"
                                    >
                                        <div className="p-1.5 bg-emerald-200/50 rounded-full">
                                            <CheckCircle2 className="h-5 w-5" />
                                        </div>
                                        <div>
                                            <span className="block font-semibold">Approva Richiesta</span>
                                            <span className="text-xs opacity-80">Assegna tecnico e avvia ordine</span>
                                        </div>
                                    </button>
                                </>
                            ) : (
                                <div className="p-3 bg-muted/50 rounded-lg border text-sm text-center text-muted-foreground">
                                    In attesa di approvazione da un supervisore.
                                </div>
                            ))}

                            {/* TimerControls removed from here */}

                            {/* Actions Workflow - Validation Step */}
                            {wo.status === 'CLOSED' && (
                                <div className="p-4 bg-gray-50 rounded-lg border flex items-center justify-center gap-2 text-gray-600 font-medium">
                                    <CheckCircle2 className="h-5 w-5 text-gray-400" />
                                    Ordine Chiuso e Archiviato
                                </div>
                            )}

                            {/* VALIDATION STEP */}
                            {(wo.status === 'PENDING_REVIEW' || wo.status === 'COMPLETED') && (canManage ? (
                                <>
                                    <button
                                        onClick={async () => {
                                            if (!confirm("Confermi la validazione e chiusura dell'ordine?")) return;
                                            await reviewWorkOrder(wo.id, 'APPROVE');
                                        }}
                                        className="w-full text-left px-4 py-3 bg-purple-50 text-purple-700 hover:bg-purple-100 border border-purple-200 rounded-lg text-sm font-medium transition-colors flex items-center gap-3 shadow-sm"
                                    >
                                        <div className="p-1.5 bg-purple-200/50 rounded-full">
                                            <CheckCircle2 className="h-5 w-5" />
                                        </div>
                                        <div>
                                            <span className="block font-semibold">Valida e Chiudi</span>
                                            <span className="text-xs opacity-80">Archivia nello storico</span>
                                        </div>
                                    </button>
                                    <button
                                        onClick={async () => {
                                            if (!confirm("Rifiutare il lavoro e rimandare al tecnico?")) return;
                                            await reviewWorkOrder(wo.id, 'REJECT');
                                        }}
                                        className="w-full text-left px-4 py-3 bg-red-50 text-red-700 hover:bg-red-100 border border-red-200 rounded-lg text-sm font-medium transition-colors flex items-center gap-3 shadow-sm"
                                    >
                                        <div className="p-1.5 bg-red-200/50 rounded-full">
                                            <AlertTriangle className="h-5 w-5" />
                                        </div>
                                        <div>
                                            <span className="block font-semibold">Rifiuta Lavoro</span>
                                            <span className="text-xs opacity-80">Torna allo stato 'In Corso'</span>
                                        </div>
                                    </button>
                                </>
                            ) : (
                                <div className="p-3 bg-muted/50 rounded-lg border text-sm text-center text-muted-foreground">
                                    In attesa di validazione finale.
                                </div>
                            ))}

                            {wo.status === 'CLOSED' && (
                                <div className="p-4 bg-gray-50 rounded-lg border flex items-center justify-center gap-2 text-gray-600 font-medium">
                                    <CheckCircle2 className="h-5 w-5 text-gray-400" />
                                    Ordine Chiuso e Archiviato
                                </div>
                            )}

                            {/* Tech Assignment (Only for Open/InProgress) */}
                            {canManage && (wo.status === 'OPEN' || wo.status === 'IN_PROGRESS') && (
                                <button
                                    onClick={() => setAssigning(true)}
                                    className="w-full text-left px-4 py-2 hover:bg-muted rounded text-sm font-medium transition-colors flex items-center gap-2 text-muted-foreground mt-2"
                                >
                                    <User className="h-4 w-4" /> Riassegna Tecnico
                                </button>
                            )}

                            {/* Cancel Action (Available unless closed) */}
                            {wo.status !== 'CLOSED' && wo.status !== 'CANCELED' && canManage && (
                                <button className="w-full text-left px-4 py-2 hover:bg-red-50 hover:text-red-600 rounded text-sm font-medium transition-colors flex items-center gap-2 text-muted-foreground mt-1">
                                    <AlertTriangle className="h-4 w-4" /> Annulla Ordine
                                </button>
                            )}
                        </div>
                    </div>

                    {/* EWO Compliance */}
                    <div className="rounded-xl border bg-card p-6 shadow-sm">
                        <h3 className="font-semibold text-sm uppercase tracking-wider text-muted-foreground mb-4">Conformità EWO</h3>
                        {wo.ewoFilled ? (
                            <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 p-3 bg-emerald-50 text-emerald-700 border border-emerald-200 rounded-lg">
                                <div className="flex items-center gap-2">
                                    <CheckCircle2 className="h-5 w-5" />
                                    <span className="font-medium">Modulo EWO Compilato & Archiviato</span>
                                </div>
                                <Link
                                    href={`/work-orders/${wo.id}/ewo`}
                                    className="text-sm underline hover:text-emerald-900 font-medium shrink-0"
                                >
                                    Vedi Modello
                                </Link>
                            </div>
                        ) : (
                            <Link
                                href={`/work-orders/${wo.id}/ewo`}
                                className="block w-full text-left px-4 py-3 bg-amber-50 text-amber-700 hover:bg-amber-100 border border-amber-200 rounded-lg text-sm font-medium transition-colors flex items-center gap-3 shadow-sm"
                            >
                                <div className="p-1.5 bg-amber-200/50 rounded-full">
                                    <AlertTriangle className="h-5 w-5" />
                                </div>
                                <div>
                                    <span className="block font-semibold">Compila Modello EWO</span>
                                    <span className="text-xs opacity-80">Necessario per chiudere l'intervento</span>
                                </div>
                            </Link>
                        )}
                    </div>

                    {/* Job Costing Widget */}
                    <div className="rounded-xl border bg-card p-6 shadow-sm">
                        <div className="flex items-center gap-2 mb-4">
                            <Banknote className="h-5 w-5 text-emerald-600" />
                            <h3 className="font-semibold text-lg">Materiali & Costi</h3>
                        </div>

                        {/* Parts Usage Section */}
                        <div className="mb-6 border-b pb-6">
                            <div className="flex items-center justify-between mb-3">
                                <h4 className="text-sm font-semibold flex items-center gap-2">
                                    <Box className="h-4 w-4" /> Materiali Utilizzati
                                </h4>
                                <button
                                    onClick={() => setIsAddingPart(!isAddingPart)}
                                    className="text-xs bg-primary/10 text-primary px-2 py-1 rounded hover:bg-primary/20"
                                >
                                    + Aggiungi
                                </button>
                            </div>

                            {isAddingPart && (
                                <form onSubmit={handleAddPart} className="bg-muted/30 p-3 rounded-lg space-y-3 mb-3 animate-in fade-in zoom-in-95">
                                    <div>
                                        <select
                                            required
                                            className="w-full text-sm rounded-md border bg-background px-3 py-2"
                                            value={selectedPartId}
                                            onChange={e => setSelectedPartId(e.target.value)}
                                        >
                                            <option value="">Seleziona Ricambio...</option>
                                            {parts.map(p => (
                                                <option key={p.id} value={p.id} disabled={p.quantity <= 0}>
                                                    {p.name} (Disp: {p.quantity})
                                                </option>
                                            ))}
                                        </select>
                                    </div>
                                    <div className="flex gap-2">
                                        <input
                                            type="number"
                                            min="1"
                                            required
                                            placeholder="Qtà"
                                            className="w-20 text-sm rounded-md border bg-background px-3 py-2"
                                            value={partQty}
                                            onChange={e => setPartQty(Number(e.target.value))}
                                        />
                                        <button type="submit" className="flex-1 bg-primary text-primary-foreground px-3 py-2 rounded text-sm font-medium">
                                            Scarica
                                        </button>
                                    </div>
                                </form>
                            )}

                            {!wo.partsUsed || wo.partsUsed.length === 0 ? (
                                <div className="text-sm text-muted-foreground italic py-1">
                                    Nessun materiale utilizzato.
                                </div>
                            ) : (
                                <div className="space-y-2">
                                    {wo.partsUsed.map((p: any, idx) => (
                                        <div key={idx} className="flex items-center justify-between text-sm p-2 bg-muted/20 rounded-md group">
                                            <span className="font-medium truncate max-w-[120px]" title={p.partName}>{p.partName}</span>
                                            <div className="flex items-center gap-3 text-muted-foreground">
                                                <span>x{p.quantity}</span>
                                                <span>€{(p.unitCost * p.quantity).toFixed(2)}</span>
                                                {canManage && (
                                                    <button
                                                        onClick={() => handleRemovePart(p.id)} // Assuming p.id is the WorkOrderPart ID
                                                        className="text-red-500 hover:text-red-700 opacity-0 group-hover:opacity-100 transition-opacity p-1"
                                                        title="Rimuovi"
                                                    >
                                                        <Trash2 className="h-3 w-3" />
                                                    </button>
                                                )}
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            )}
                        </div>

                        <div className="space-y-3 mb-2">
                            <div className="flex justify-between text-sm">
                                <span className="text-muted-foreground">Costo Ricambi</span>
                                <span className="font-mono">€{partsCost.toFixed(2)}</span>
                            </div>
                            <div className="flex justify-between text-sm">
                                <span className="text-muted-foreground">Costo Manodopera</span>
                                <span className="font-mono">€{laborCost.toFixed(2)}</span>
                            </div>
                            <div className="pt-2 border-t flex justify-between font-bold text-base">
                                <span>Totale</span>
                                <span>€{totalCost.toFixed(2)}</span>
                            </div>
                        </div>
                    </div>

                    {/* Labor Tracking */}
                    <div className="rounded-xl border bg-card p-6 shadow-sm">
                        <div className="flex items-center justify-between mb-4">
                            <h3 className="font-semibold flex items-center gap-2">
                                <Clock className="h-4 w-4" /> Manodopera
                            </h3>
                            <button
                                onClick={() => setIsAddingLabor(!isAddingLabor)}
                                className="text-xs bg-primary/10 text-primary px-2 py-1 rounded hover:bg-primary/20"
                            >
                                + Aggiungi Ore
                            </button>
                        </div>

                        {isAddingLabor && (
                            <form onSubmit={handleAddLabor} className="bg-muted/30 p-4 rounded-lg space-y-3 animate-in fade-in zoom-in-95">
                                <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
                                    <div className="sm:col-span-2">
                                        <label className="text-xs font-medium mb-1 block">Tecnico</label>
                                        <select
                                            required
                                            className="w-full text-sm rounded-md border bg-background px-3 py-2"
                                            value={selectedTechId}
                                            onChange={e => setSelectedTechId(e.target.value)}
                                        >
                                            <option value="">Seleziona Tecnico...</option>
                                            {technicians.map(t => (
                                                <option key={t.id} value={t.id}>
                                                    {t.name} (€{t.hourlyRate}/h)
                                                </option>
                                            ))}
                                        </select>
                                    </div>
                                    <div>
                                        <label className="text-xs font-medium mb-1 block">Ore</label>
                                        <input
                                            type="number"
                                            min="0.5"
                                            step="0.5"
                                            required
                                            className="w-full text-sm rounded-md border bg-background px-3 py-2"
                                            value={laborHours}
                                            onChange={e => setLaborHours(Number(e.target.value))}
                                        />
                                    </div>
                                </div>
                                <div className="flex justify-end">
                                    <button type="submit" className="bg-primary text-primary-foreground px-3 py-1.5 rounded text-sm font-medium">
                                        Aggiungi
                                    </button>
                                </div>
                            </form>
                        )}

                        {!wo.laborLogs || wo.laborLogs.length === 0 ? (
                            <div className="text-sm text-muted-foreground italic py-2">
                                Nessuna attività registrata.
                            </div>
                        ) : (
                            <div className="space-y-2">
                                {wo.laborLogs.map((log) => (
                                    <div key={log.id} className="flex items-center justify-between text-sm p-2 bg-muted/20 rounded-md">
                                        <span className="font-medium">{log.technicianName}</span>
                                        <div className="flex items-center gap-4 text-muted-foreground">
                                            <span>{log.hours}h</span>
                                            <span className="text-xs">{new Date(log.date).toLocaleDateString()}</span>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        )}
                    </div>


                </div>

                <div className="space-y-6">
                    <div className="rounded-xl border bg-card p-6 shadow-sm space-y-4">
                        <h3 className="font-semibold text-sm uppercase tracking-wider text-muted-foreground">Dettagli</h3>

                        <div className="flex justify-between items-center py-2 border-b">
                            <span className="text-sm">Stato</span>
                            <WOStatusBadge status={wo.status} />
                        </div>

                        <div className="flex justify-between items-center py-2 border-b">
                            <span className="text-sm">Priorità</span>
                            <WOPriorityBadge priority={wo.priority} />
                        </div>

                        <div className="flex items-center gap-3 py-2 border-b">
                            <User className="h-4 w-4 text-muted-foreground" />
                            <div className="flex flex-col">
                                <span className="text-xs text-muted-foreground">Assegnato a</span>
                                <div className="text-sm font-medium flex flex-wrap gap-1">
                                    {wo.technicians && wo.technicians.length > 0 ? (
                                        wo.technicians.map((t: any) => (
                                            <span key={t.id} className="after:content-[','] last:after:content-[''] mr-1">
                                                {t.name}
                                            </span>
                                        ))
                                    ) : (
                                        <span>{wo.assignedTo || 'Non assegnato'}</span>
                                    )}
                                </div>
                            </div>
                        </div>

                        <div className="flex items-center gap-3 py-2">
                            <Calendar className="h-4 w-4 text-muted-foreground" />
                            <div className="flex flex-col">
                                <span className="text-xs text-muted-foreground">Scadenza</span>
                                <span className="text-sm font-medium">{wo.dueDate}</span>
                            </div>
                        </div>
                    </div>

