export async function getPlannerUnassignedItems() {
    try {
        // 1. Unassigned Work Orders
        const workOrders = await prisma.workOrder.findMany({
            where: {
                assignedTechnicianId: null,
                status: { in: ["OPEN", "PENDING_APPROVAL"] }
